import { test, expect, type BrowserContext, type Page } from '@playwright/test';
import { createServer } from 'node:http';
import { existsSync, readFileSync } from 'node:fs';
import type { AddressInfo } from 'node:net';

/** The worker is generated by `npm run build:sw`, which runs before the Playwright web server starts. */
const WORKER_PATH = 'public/sw.js';

// The headless shell cannot grant the notifications permission; full Chromium in new headless mode can.
test.use({ channel: 'chromium' });

/** Serves the real worker and an empty page that registers it, on a secure loopback origin. */
async function startWorkerServer() {
  const server = createServer((request, response) => {
    if (request.url === '/sw.js') { response.setHeader('Content-Type', 'text/javascript'); response.setHeader('Service-Worker-Allowed', '/'); response.end(readFileSync(WORKER_PATH)); return; }
    if (request.url === '/offline.html') { response.setHeader('Content-Type', 'text/html'); response.end(readFileSync('public/offline.html')); return; }
    if (request.url?.startsWith('/icons/')) { response.setHeader('Content-Type', 'image/png'); response.end(readFileSync('public/icons/icon-192.png')); return; }
    response.setHeader('Content-Type', 'text/html');
    response.end('<!doctype html><html lang="es"><meta charset="utf-8"><body><script>window.workerMessages = []; navigator.serviceWorker.addEventListener("message", (event) => window.workerMessages.push(event.data)); navigator.serviceWorker.register("/sw.js");</script></body></html>');
  });
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  return { server, origin: `http://127.0.0.1:${(server.address() as AddressInfo).port}` };
}

/** Delivers a push through the DevTools protocol, the same path as the "Push" button of Chrome DevTools. */
async function deliverPush(context: BrowserContext, page: Page, origin: string, payload: unknown) {
  const session = await context.newCDPSession(page);
  const registration = new Promise<string>((resolve) => {
    session.on('ServiceWorker.workerRegistrationUpdated', ({ registrations }) => {
      const match = registrations.find((item) => item.scopeURL.startsWith(origin) && !item.isDeleted);
      if (match) resolve(match.registrationId);
    });
  });
  await session.send('ServiceWorker.enable');
  await session.send('ServiceWorker.deliverPushMessage', { origin, registrationId: await registration, data: JSON.stringify(payload) });
}

async function shownNotifications(page: Page) {
  return page.evaluate(async () => (await (await navigator.serviceWorker.ready).getNotifications()).map((notification) => ({
    title: notification.title, body: notification.body, tag: notification.tag, renotify: (notification as Notification & { renotify?: boolean }).renotify,
    actions: ((notification as Notification & { actions?: Array<{ action: string; title: string }> }).actions ?? []).map((action) => action.action),
    data: notification.data as unknown,
  })));
}

test('un timbrazo muestra respuestas y una nota posterior reemplaza el aviso sonando de nuevo', async ({ browser }) => {
  test.skip(!existsSync(WORKER_PATH), 'Requiere el service worker generado por npm run build:sw.');
  const { server, origin } = await startWorkerServer();
  const context = await browser.newContext();
  try {
    await context.grantPermissions(['notifications'], { origin });
    const page = await context.newPage();
    await page.goto(origin);
    await page.evaluate(() => navigator.serviceWorker.ready);
    const visitId = '0d9c2f5e-3f0a-4c49-9d5b-7f3e2a1b4c6d';
    await deliverPush(context, page, origin, { kind: 'ring', title: 'Hay alguien en la puerta', body: 'Soy Juan', tag: visitId, visitId, url: `/?view=history&visit=${visitId}`, replies: [{ reply: 'coming', title: 'Ya voy' }, { reply: 'leave', title: 'Dejalo en la puerta' }] });
    await expect.poll(() => shownNotifications(page)).toEqual([{ title: 'Hay alguien en la puerta', body: 'Soy Juan', tag: visitId, renotify: true, actions: ['reply:coming', 'reply:leave'], data: { url: `/?view=history&visit=${visitId}`, visitId } }]);
    await expect.poll(() => page.evaluate(() => (window as unknown as { workerMessages: unknown[] }).workerMessages)).toContainEqual({ type: 'ringgg:push', visitId });

    await deliverPush(context, page, origin, { kind: 'note', title: 'Te dejaron un mensaje', body: 'Llamame al 11 5555 5555', tag: visitId, visitId, url: `/?view=history&visit=${visitId}`, replies: [] });
    await expect.poll(() => shownNotifications(page)).toEqual([{ title: 'Te dejaron un mensaje', body: 'Llamame al 11 5555 5555', tag: visitId, renotify: true, actions: [], data: { url: `/?view=history&visit=${visitId}`, visitId } }]);
  } finally {
    await context.close();
    await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
  }
});

test('un payload ajeno nunca abre otro origen desde la notificación', async ({ browser }) => {
  test.skip(!existsSync(WORKER_PATH), 'Requiere el service worker generado por npm run build:sw.');
  const { server, origin } = await startWorkerServer();
  const context = await browser.newContext();
  try {
    await context.grantPermissions(['notifications'], { origin });
    const page = await context.newPage();
    await page.goto(origin);
    await page.evaluate(() => navigator.serviceWorker.ready);
    await deliverPush(context, page, origin, { kind: 'test', title: 'Prueba', body: 'Prueba', tag: 'test-tag', url: 'https://evil.example/robar', replies: [{ reply: 'coming', title: 'Ya voy' }] });
    await expect.poll(() => shownNotifications(page)).toEqual([{ title: 'Prueba', body: 'Prueba', tag: 'test-tag', renotify: true, actions: [], data: { url: '/' } }]);
  } finally {
    await context.close();
    await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
  }
});
